// Zero-allocation CSV field split
static void SumPrices(ReadOnlySpan<char> line, ref decimal total)
{
    foreach (Range field in line.Split(',')) // span-based Split, no substrings
    {
        ReadOnlySpan<char> slice = line[field];
        if (decimal.TryParse(slice, out decimal price)) { total += price; }
    }
}

